// New York (Manhattan en Brooklyn aan de East River), elf buurten naar Lonely Planet. Basis Nederlands, Engelse overlay onderaan.
// Gebouwen uit OpenStreetMap (hoogtes uit de NYC-gebouwendata), water via de kustlijn.
// Manhattan-raster: at(avenue, straat). 5th Ave = 0, westwaarts positief, oostwaarts negatief.
const at = (a, s) => [+(40.7532 + 0.00145 * a + 0.000635 * (s - 42)).toFixed(5), +(-73.9810 - 0.0031 * a + 0.00046 * (s - 42)).toFixed(5)];

